 38	    /// Predict hyperparameters from instance features.
 39	    pub fn predict(&self, features: &InstanceFeatures) -> Result<SolverHyperparams> {
 40	        let x = features.to_vector();
 41	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 42	        let h1 = self.lin1.forward(&input)?.relu()?;
 43	        let out = self.lin2.forward(&h1)?;
 44	        let vals: Vec<f32> = out.squeeze(0)?.to_vec1()?;
 45	        let v = vals.as_slice();
 46	
 47	        // Clamp each output to [0, 1] and scale to parameter range
 48	        let max_iter = (100.0 + v[0].clamp(0.0, 1.0) as f64 * 9900.0) as u32;
 49	        let temperature = 1.0 + v[1].clamp(0.0, 1.0) as f64 * 999.0;
 50	        let tabu_tenure = (1.0 + v[2].clamp(0.0, 1.0) as f64 * 49.0).round() as usize;
 51	        let cooling_rate = 0.8 + v[3].clamp(0.0, 1.0) as f64 * 0.199;
 52	        let neighbourhood_radius = (1.0 + v[4].clamp(0.0, 1.0) as f64 * 19.0).round() as usize;
 53	
 54	        Ok(SolverHyperparams {
 55	            max_iterations: max_iter,
 56	            temperature,
 57	            tabu_tenure,
 58	            cooling_rate,
 59	            neighbourhood_radius,
 60	            model_used: true,
 61	        })
 62	    }
 63	}
