443	pub struct NeuralGuidedSolver;
444	
445	#[async_trait::async_trait]
446	impl VRPSolver for NeuralGuidedSolver {
447	    fn id(&self) -> &str {
448	        "neural_guided"
449	    }
450	
451	    fn label(&self) -> &str {
452	        "Neural-Guided (2-Opt + Or-Opt)"
453	    }
