   1	//! rmpca-mcp-server — MCP server exposing the route optimization pipeline.
   2	//!
   3	//! Tools: extract_overture, extract_osm, compile, optimize,
   4	//!        clean, vrp_solve, elevation_query, elevation_profile,
   5	//!        predict_solver, score_route, route_embedding, pipeline,
   6	//!        haversine_distance, get_valhalla_matrix, inspect_rmp,
   7	//!        list_solvers, elevation_stats, dem_info, fuel_estimate
   8	//!
   9	//! Runs over stdio with JSON-RPC 2.0 framing (one line per message).
  10	//!
  11	//! Connect from any MCP client by adding to the client config:
  12	//!
  13	//! ```json
  14	//! {
  15	//!   "mcpServers": {
  16	//!     "rmpca": {
  17	//!       "command": "cargo",
  18	//!       "args": ["run", "--bin", "rmpca-mcp-server", "--release"]
  19	//!     }
  20	//!   }
  21	//! }
  22	//! ```
  23	
