 912	fn parse_bbox(args: &Value) -> anyhow::Result<BBoxRequest> {
 913	    let bbox = args
 914	        .get("bbox")
 915	        .ok_or_else(|| anyhow::anyhow!("Missing 'bbox' parameter"))?;
 916	    Ok(BBoxRequest {
 917	        min_lon: bbox
 918	            .get("min_lon")
 919	            .and_then(|v| v.as_f64())
 920	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lon required"))?,
 921	        min_lat: bbox
 922	            .get("min_lat")
 923	            .and_then(|v| v.as_f64())
 924	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lat required"))?,
 925	        max_lon: bbox
 926	            .get("max_lon")
 927	            .and_then(|v| v.as_f64())
 928	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lon required"))?,
 929	        max_lat: bbox
 930	            .get("max_lat")
 931	            .and_then(|v| v.as_f64())
 932	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lat required"))?,
 933	    })
 934	}
