 21	//! Dynamic solver registry: built-ins first, then dynamically registered solvers.
 22	
 23	use super::solvers::clarke_wright::ClarkeWrightSolver;
 24	use super::solvers::default::DefaultSolver;
 25	#[cfg(feature = "ml")]
 26	use super::solvers::neural_guided::NeuralGuidedSolver;
 27	use super::solvers::or_opt::OrOptSolver;
 28	use super::solvers::sweep::SweepSolver;
 29	use super::solvers::two_opt::TwoOptSolver;
 30	use super::types::{VRPSolver, VRPSolverInput, VRPSolverOutput};
 31	use std::collections::HashMap;
 32	use std::sync::{Arc, OnceLock, RwLock};
 33	
 34	static REGISTRY: OnceLock<RwLock<SolverRegistryInner>> = OnceLock::new();
 35	
 36	fn registry() -> &'static RwLock<SolverRegistryInner> {
 37	    REGISTRY.get_or_init(|| RwLock::new(SolverRegistryInner::new()))
 38	}
 39	
 40	struct SolverRegistryInner {
 41	    solvers: HashMap<String, Arc<dyn VRPSolver>>,
 42	    builtin_ids: Vec<String>,
 43	    dynamic_order: Vec<String>,
 44	}
 45	
 46	impl SolverRegistryInner {
 47	    fn new() -> Self {
 48	        let mut builtins: Vec<Arc<dyn VRPSolver>> = vec![
 49	            Arc::new(ClarkeWrightSolver),
 50	            Arc::new(SweepSolver),
 51	            Arc::new(OrOptSolver),
 52	            Arc::new(TwoOptSolver),
 53	        ];
 54	        #[cfg(feature = "ml")]
 55	        builtins.push(Arc::new(NeuralGuidedSolver));
 56	        builtins.push(Arc::new(DefaultSolver));
 57	
 58	        let builtin_ids: Vec<String> = builtins.iter().map(|s| s.id().to_string()).collect();
 59	        let mut solvers = HashMap::new();
 60	        for s in builtins {
 61	            let id = s.id().to_string();
 62	            solvers.insert(id, s);
 63	        }
 64	        Self {
 65	            solvers,
 66	            builtin_ids,
 67	            dynamic_order: Vec::new(),
 68	        }
 69	    }
 70	}
 71	
 72	/// Register a custom solver. If the id already exists, it is replaced.
 73	pub fn register_solver(solver: Arc<dyn VRPSolver>) {
 74	    let id = solver.id().to_string();
 75	    let mut reg = registry().write().unwrap();
 76	    let had = reg.solvers.contains_key(&id);
 77	    reg.solvers.insert(id.clone(), solver);
 78	    if !had && !reg.builtin_ids.contains(&id) {
 79	        reg.dynamic_order.push(id);
 80	    }
 81	}
 82	
 83	/// Unregister a solver by id. Built-in solver ids are ignored.
 84	/// Returns true if a dynamic solver was removed.
 85	pub fn unregister_solver(id: &str) -> bool {
 86	    let mut reg = registry().write().unwrap();
 87	    if reg.builtin_ids.contains(&id.to_string()) {
 88	        return false;
 89	    }
 90	    let removed = reg.solvers.remove(id).is_some();
 91	    if removed {
 92	        reg.dynamic_order.retain(|x| x != id);
 93	    }
 94	    removed
 95	}
 96	
 97	/// Return the ordered list of solvers: built-ins first, then dynamically registered.
 98	pub fn get_solver_list() -> Vec<String> {
 99	    let reg = registry().read().unwrap();
100	    let mut ids: Vec<String> = reg.builtin_ids.clone();
101	    for id in &reg.dynamic_order {
102	        if reg.solvers.contains_key(id) {
103	            ids.push(id.clone());
104	        }
105	    }
106	    ids
107	}
108	
109	/// Solve using a solver by id. Falls back to default.
110	pub async fn solve_with(id: &str, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
111	    // Clone the Arc out before .await so we don't hold RwLockReadGuard across await.
112	    let solver: Arc<dyn VRPSolver> = {
113	        let reg = registry().read().unwrap();
114	        match reg.solvers.get(id).or_else(|| reg.solvers.get("default")) {
115	            Some(s) => Arc::clone(s),
116	            None => return Err(format!("Solver '{id}' not found and no default available")),
117	        }
118	    };
119	    solver.solve(input).await
120	}
121	
122	/// Algorithm options for UI dropdowns.
123	pub fn get_algorithm_options() -> Vec<(String, String)> {
124	    let ids = get_solver_list();
125	    let reg = registry().read().unwrap();
126	    ids.iter()
127	        .filter_map(|id| {
128	            reg.solvers
129	                .get(id)
130	                .map(|s| (s.id().to_string(), s.label().to_string()))
131	        })
132	        .collect()
133	}
