2113	fn handle_parse_routing_query(args: &Value) -> Result<Value> {
2114	    let query = args
2115	        .get("query")
2116	        .and_then(|v| v.as_str())
2117	        .ok_or_else(|| anyhow::anyhow!("Missing 'query' parameter"))?;
