2125	            let mut parser = QwenNLParser::new()?;
2126	            let json_str = parser.parse_llm(query)?;
2127	            
2128	            // Try to parse the LLM output as JSON. If it fails, fallback to regex.
2129	            match serde_json::from_str::<Value>(&json_str) {
2130	                Ok(json) => {
2131	                    return Ok(json!({
2132	                        "variant": json.get("variant").and_then(|v| v.as_str()).unwrap_or("cvrp"),
2133	                        "config": json,
