  1	//! Learned solver selector using a small MLP in Candle.
  2	//!
  3	//! Replaces the rule-based `predict_solver` in `ml_legacy.rs`.
  4	//!
  5	//! Architecture: 28 → 128 → 64 → 5  (input → hidden → hidden → num_solvers)
  6	//! Activation: ReLU hidden, Softmax output.
  7	//!
  8	//! Weights are loaded from a safetensors file at runtime.
  9	//! If the model file is missing, falls back to the rule-based selector.
 10	
 11	use crate::core::ml::features::InstanceFeatures;
 12	use crate::core::ml_legacy::{predict_solver as rule_predict_solver, SolverPrediction};
 13	use crate::core::vrp::types::{VRPSolverInput, VrpObjective};
 14	use anyhow::{Context, Result};
 15	use candle_core::{Device, Tensor, DType};
 16	use candle_nn::{linear, Module, VarBuilder, Linear};
 17	use serde::{Deserialize, Serialize};
 18	use std::path::Path;
 19	
 20	const NUM_FEATURES: usize = 28;
 21	const HIDDEN1: usize = 128;
 22	const HIDDEN2: usize = 64;
 23	const NUM_SOLVERS: usize = 5;
 24	
 25	const SOLVER_IDS: [&str; NUM_SOLVERS] = [
 26	    "default",
 27	    "clarke_wright",
 28	    "sweep",
 29	    "two_opt",
 30	    "or_opt",
 31	];
 32	
 33	/// Learned MLP solver selector.
 34	pub struct NeuralSelector {
 35	    lin1: Linear,
 36	    lin2: Linear,
 37	    lin3: Linear,
 38	    device: Device,
 39	}
 40	
 41	impl NeuralSelector {
 42	    /// Load from a safetensors file.
 43	    pub fn from_file(path: &Path) -> Result<Self> {
 44	        let device = crate::core::ml::best_device()?;
 45	        let tensors = candle_core::safetensors::load(path, &device)
 46	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 47	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 48	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 49	        let lin2 = linear(HIDDEN1, HIDDEN2, vb.pp("lin2"))?;
 50	        let lin3 = linear(HIDDEN2, NUM_SOLVERS, vb.pp("lin3"))?;
 51	        Ok(Self { lin1, lin2, lin3, device })
 52	    }
 53	
 54	    /// Predict solver probabilities from instance features.
 55	    pub fn predict(&self,
 56	        features: &InstanceFeatures,
 57	    ) -> Result<NeuralPrediction> {
 58	        let x = features.to_vector();
 59	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 60	        let h1 = self.lin1.forward(&input)?.relu()?;
 61	        let h2 = self.lin2.forward(&h1)?.relu()?;
 62	        let logits = self.lin3.forward(&h2)?;
 63	        let probs = candle_nn::ops::softmax(&logits, 1)?;
 64	        let probs_vec: Vec<f32> = probs.squeeze(0)?.to_vec1()?;
 65	        let mut indexed: Vec<(usize, f32)> = probs_vec.iter().enumerate().map(|(i, &p)| (i, p)).collect();
 66	        indexed.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
 67	
 68	        let best_idx = indexed[0].0;
 69	        let best_prob = indexed[0].1;
 70	        let runner_up = indexed.get(1).map(|(i, p)| (SOLVER_IDS[*i].to_string(), *p));
 71	
 72	        let all_scores: Vec<(String, f64)> = indexed
 73	            .iter()
 74	            .map(|(i, p)| (SOLVER_IDS[*i].to_string(), *p as f64))
 75	            .collect();
 76	
 77	        Ok(NeuralPrediction {
 78	            recommended: SOLVER_IDS[best_idx].to_string(),
 79	            confidence: best_prob as f64,
 80	            runner_up,
 81	            all_scores,
 82	        })
 83	    }
 84	}
 85	
 86	/// Prediction result from the neural selector.
 87	#[derive(Debug, Clone, Serialize, Deserialize)]
 88	pub struct NeuralPrediction {
 89	    pub recommended: String,
 90	    pub confidence: f64,
 91	    pub runner_up: Option<(String, f32)>,
 92	    pub all_scores: Vec<(String, f64)>,
 93	}
 94	
 95	/// High-level API: predict the best solver for a VRP instance.
 96	///
 97	/// Tries to load the neural model from `model_path`. If missing or failed,
 98	/// falls back to the legacy rule-based selector.
 99	pub fn predict_solver(
100	    input: &VRPSolverInput,
101	    model_path: Option<&Path>,
102	) -> Result<NeuralPrediction> {
103	    let features = InstanceFeatures::from_input(input);
104	
105	    if let Some(path) = model_path {
106	        if path.exists() {
107	            match NeuralSelector::from_file(path) {
108	                Ok(selector) => {
109	                    match selector.predict(&features) {
110	                        Ok(pred) => return Ok(pred),
111	                        Err(e) => {
112	                            tracing::warn!("Neural selector inference failed: {}. Falling back to rule-based.", e);
113	                        }
114	                    }
115	                }
116	                Err(e) => {
117	                    tracing::warn!("Failed to load neural selector: {}. Falling back to rule-based.", e);
118	                }
119	            }
120	        }
121	    }
122	
123	    // Fallback: rule-based
124	    let legacy = rule_predict_solver(&crate::core::ml_legacy::RouteFeatures::from_input(input)
125	    );
126	    let all_scores: Vec<(String, f64)> = legacy.all_scores;
127	    let runner_up = legacy.runner_up.map(|(id, score)| (id, score as f32));
128	    Ok(NeuralPrediction {
129	        recommended: legacy.recommended,
130	        confidence: legacy.confidence,
131	        runner_up,
132	        all_scores,
133	    })
134	}
135	
136	/// Default model path relative to the executable.
137	pub fn default_model_path() -> std::path::PathBuf {
138	    // 1. Try relative to current executable
139	    if let Ok(exe_path) = std::env::current_exe() {
140	        if let Some(exe_dir) = exe_path.parent() {
141	            let p = exe_dir.join("models").join("solver_selector.safetensors");
142	            if p.exists() {
143	                return p;
144	            }
145	        }
146	    }
147	
148	    // 2. Try relative to current working directory
149	    let p = std::path::PathBuf::from("models/solver_selector.safetensors");
150	    if p.exists() {
151	        return p;
152	    }
153	
154	    // Fallback
155	    std::env::current_exe()
156	        .unwrap_or_else(|_| std::path::PathBuf::from("."))
157	        .parent()
158	        .unwrap_or(std::path::Path::new("."))
159	        .join("models")
160	        .join("solver_selector.safetensors")
161	}
