  9	pub struct DefaultSolver;
 10	
 11	#[async_trait::async_trait]
 12	impl VRPSolver for DefaultSolver {
 13	    fn id(&self) -> &str {
 14	        "default"
 15	    }
 16	    fn label(&self) -> &str {
 17	        "Default (Zone-cluster + 2-Opt)"
 18	    }
 19	    fn requires_matrix(&self) -> bool {
 20	        true
 21	    }
 22	
 23	    async fn solve(&self, input: &VRPSolverInput) -> Result<VRPSolverOutput, String> {
 24	        let matrix = input
 25	            .matrix
 26	            .as_ref()
 27	            .ok_or("Default solver requires a distance matrix")?;
 28	        let n = input.locations.len();
 29	
 30	        let num_zones = ((n as f64).sqrt().ceil() as usize).clamp(2, 6);
 31	        let clusters = cluster_by_zones(&input.locations, num_zones);
 32	        let ordered_clusters = order_clusters_by_start(&clusters, &input.locations, 0);
 33	
 34	        let mut route_indices: Vec<usize> = Vec::new();
 35	        for cluster in &ordered_clusters {
 36	            let start_in_cluster = cluster.iter().position(|&i| i == 0);
 37	            let start_idx = start_in_cluster.unwrap_or(0);
 38	            let segment = nearest_neighbor_route(matrix, cluster, start_idx);
 39	            route_indices.extend(segment);
 40	        }
 41	
 42	        let mut with_return = route_indices;
 43	        with_return.push(0);
 44	
 45	        let max_iter = input.hyperparams.as_ref().map(|p| p.max_iterations).unwrap_or(300);
 46	        let improved = two_opt_improve(matrix, &with_return, max_iter);
 47	
 48	        let mut total_dist = 0.0;
 49	        let mut total_time = 0.0;
 50	        for i in 0..improved.len() - 1 {
 51	            total_dist += matrix_get_dist(matrix, improved[i], improved[i + 1]);
 52	            total_time += matrix_get_time(matrix, improved[i], improved[i + 1]);
 53	        }
 54	
 55	        let result = crate::core::vrp::types::SolveResult {
 56	            routes: vec![improved],
 57	            total_distance: total_dist,
 58	            total_time,
 59	        };
 60	        
 61	        Ok(result.into_output(input))
 62	    }
 63	    fn clone_box(&self) -> Box<dyn VRPSolver> {
 64	        Box::new(DefaultSolver)
 65	    }
 66	}
