  1	//! Or-Opt: sweep construction + iterative relocation of chains of 1-3
  2	//! consecutive stops to the best position across all routes.
  3	
  4	use super::super::types::*;
  5	use super::super::utils::{matrix_get_dist, matrix_get_time};
  6	
  7	fn solve(
  8	    matrix: &DistMatrix,
  9	    locations: &[VRPSolverStop],
 10	    num_vehicles: usize,
 11	    balance_load: bool,
 12	    hyperparams: Option<&SolverHyperparams>,
 13	) -> SolveResult {
 14	    let n = matrix.len();
 15	    if n <= 1 {
 16	        return SolveResult {
 17	            routes: vec![vec![0]],
 18	            total_distance: 0.0,
 19	            total_time: 0.0,
 20	        };
 21	    }
 22	
 23	    let mut routes = crate::core::vrp::utils::build_sweep_routes(matrix, locations, num_vehicles);
 24	
 25	    let intermediate_count = |r: &[usize]| -> usize {
 26	        if r.len() > 2 {
 27	            r.len() - 2
 28	        } else {
 29	            0
 30	        }
 31	    };
 32	
 33	    let mut improved = true;
 34	    let max_passes = hyperparams.map(|p| p.max_iterations / 4).unwrap_or(100).max(1);
 35	    let mut passes = 0;
 36	
 37	    while improved && passes < max_passes {
 38	        improved = false;
 39	        passes += 1;
 40	
 41	        'outer: for ri in 0..routes.len() {
 42	            let route_a_len = routes[ri].len();
 43	            if route_a_len < 3 {
 44	                continue;
 45	            }
 46	
 47	            for k in 1..=3usize {
 48	                for pos in 1..(route_a_len.saturating_sub(k - 1)) {
 49	                    if pos + k > route_a_len - 1 {
 50	                        break;
 51	                    }
 52	                    let chain_first = routes[ri][pos];
 53	                    let chain_last = routes[ri][pos + k - 1];
 54	                    let prev = routes[ri][pos - 1];
 55	                    let next_idx = pos + k;
 56	                    let next = if next_idx < routes[ri].len() {
 57	                        routes[ri][next_idx]
 58	                    } else {
 59	                        routes[ri][0]
 60	                    };
 61	
 62	                    let remove_gain = matrix_get_dist(matrix, prev, chain_first)
 63	                        + matrix_get_dist(matrix, chain_last, next)
 64	                        - matrix_get_dist(matrix, prev, next);
 65	
 66	                    let mut best_gain = 1e-9;
 67	                    let mut best_rj: Option<usize> = None;
 68	                    let mut best_ins: Option<usize> = None;
 69	                    let mut best_rev = false;
 70	
 71	                    for (rj, _) in routes.iter().enumerate() {
 72	                        let route_b_len = routes[rj].len();
 73	                        for ins in 0..route_b_len.saturating_sub(1) {
 74	                            if rj == ri && ins >= pos.saturating_sub(1) && ins < pos + k {
 75	                                continue;
 76	                            }
 77	
 78	                            let a_node = routes[rj][ins];
 79	                            let b_node = if ins + 1 < route_b_len {
 80	                                routes[rj][ins + 1]
 81	                            } else {
 82	                                routes[rj][0]
 83	                            };
 84	
 85	                            let cost_fwd = matrix_get_dist(matrix, a_node, chain_first)
 86	                                + matrix_get_dist(matrix, chain_last, b_node)
 87	                                - matrix_get_dist(matrix, a_node, b_node);
 88	                            if remove_gain - cost_fwd > best_gain {
 89	                                best_gain = remove_gain - cost_fwd;
 90	                                best_rj = Some(rj);
 91	                                best_ins = Some(ins);
 92	                                best_rev = false;
 93	                            }
 94	
 95	                            if k > 1 {
 96	                                let cost_rev = matrix_get_dist(matrix, a_node, chain_last)
 97	                                    + matrix_get_dist(matrix, chain_first, b_node)
 98	                                    - matrix_get_dist(matrix, a_node, b_node);
 99	                                if remove_gain - cost_rev > best_gain {
100	                                    best_gain = remove_gain - cost_rev;
101	                                    best_rj = Some(rj);
102	                                    best_ins = Some(ins);
103	                                    best_rev = true;
104	                                }
105	                            }
106	                        }
107	                    }
108	
109	                    let Some(rj_val) = best_rj else { continue };
110	                    let Some(ins_val) = best_ins else { continue };
111	
112	                    if balance_load && rj_val != ri {
113	                        let new_count_a = intermediate_count(&routes[ri]).saturating_sub(k);
114	                        let new_count_b = intermediate_count(&routes[rj_val]).saturating_add(k);
115	                        let counts: Vec<usize> = routes
116	                            .iter()
117	                            .enumerate()
118	                            .map(|(idx, r)| {
119	                                if idx == ri {
120	                                    new_count_a
121	                                } else if idx == rj_val {
122	                                    new_count_b
123	                                } else {
124	                                    intermediate_count(r)
125	                                }
126	                            })
127	                            .collect();
128	                        let max_c = *counts.iter().max().unwrap_or(&0);
129	                        let min_c = *counts.iter().min().unwrap_or(&0);
130	                        if max_c - min_c > 1 {
131	                            continue;
132	                        }
133	                    }
134	
135	                    improved = true;
136	                    let chain: Vec<usize> = routes[ri][pos..pos + k].to_vec();
137	                    let insert_chain: Vec<usize> = if best_rev {
138	                        chain.iter().copied().rev().collect()
139	                    } else {
140	                        chain.clone()
141	                    };
142	
143	                    if rj_val == ri {
144	                        let mut r = routes[ri].clone();
145	                        r.splice(pos..pos + k, std::iter::empty());
146	                        let adj_ins = if ins_val >= pos { ins_val - k } else { ins_val };
147	                        let insert_at = adj_ins + 1;
148	                        let mut result = r[..insert_at].to_vec();
149	                        result.extend_from_slice(&insert_chain);
150	                        result.extend_from_slice(&r[insert_at..]);
151	                        routes[ri] = result;
152	                    } else {
153	                        let mut r_a = routes[ri].clone();
154	                        r_a.splice(pos..pos + k, std::iter::empty());
155	                        routes[ri] = r_a;
156	                        let r_b = routes[rj_val].clone();
157	                        let insert_at = ins_val + 1;
158	                        let mut result = r_b[..insert_at].to_vec();
159	                        result.extend_from_slice(&insert_chain);
160	                        result.extend_from_slice(&r_b[insert_at..]);
161	                        routes[rj_val] = result;
162	                    }
163	
164	                    break 'outer;
165	                }
166	            }
167	        }
168	    }
169	
170	    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
171	    if final_routes.is_empty() {
172	        return SolveResult {
173	            routes: vec![vec![0, 0]],
174	            total_distance: 0.0,
175	            total_time: 0.0,
176	        };
177	    }
178	
179	    let mut total_distance = 0.0;
180	    let mut total_time = 0.0;
181	    for r in &final_routes {
182	        for i in 0..r.len() - 1 {
183	            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
184	            total_time += matrix_get_time(matrix, r[i], r[i + 1]);
185	        }
186	    }
187	
188	    SolveResult {
189	        routes: final_routes,
190	        total_distance,
191	        total_time,
192	    }
193	}
