170	/// Fetch a real-road distance/time matrix from Valhalla.
171	pub async fn get_valhalla_matrix(locations: &[VRPSolverStop]) -> Result<DistMatrix, String> {
172	    let url = "https://valhalla1.openstreetmap.de/sources_to_targets";
173	    let locs: Vec<serde_json::Value> = locations
174	        .iter()
175	        .map(|l| serde_json::json!({"lat": l.lat, "lon": l.lon}))
176	        .collect();
177	
178	    let body = serde_json::json!({
179	        "sources": locs,
180	        "targets": locs,
181	        "costing": "auto",
182	        "directions_options": { "units": "kilometers" }
183	    });
184	
185	    let client = reqwest::Client::new();
186	    let resp = client
187	        .post(url)
188	        .json(&body)
189	        .send()
190	        .await
191	        .map_err(|e| format!("Valhalla request failed: {e}"))?;
192	
193	    if !resp.status().is_success() {
194	        return Err(format!("Valhalla HTTP {}", resp.status()));
195	    }
196	
197	    let data: serde_json::Value = resp
198	        .json()
199	        .await
200	        .map_err(|e| format!("Valhalla parse error: {e}"))?;
201	
202	    let stt = data
203	        .get("sources_to_targets")
204	        .ok_or("Invalid Valhalla response: missing sources_to_targets")?;
205	
206	    let rows = stt
207	        .as_array()
208	        .ok_or("Invalid Valhalla response: sources_to_targets not an array")?;
209	    let n = rows.len();
210	    let mut matrix = Vec::with_capacity(n);
211	    for row_val in rows {
212	        let row = row_val.as_array().ok_or("Invalid Valhalla row")?;
213	        let mut matrix_row = Vec::with_capacity(n);
214	        for cell_val in row {
215	            let cell = cell_val.as_object();
216	            let (dist, time) = match cell {
217	                Some(c) => (
218	                    c.get("distance").and_then(|v| v.as_f64()).unwrap_or(0.0),
219	                    c.get("time").and_then(|v| v.as_f64()).unwrap_or(0.0),
220	                ),
221	                None => (0.0, 0.0),
222	            };
223	            matrix_row.push(DistCell {
224	                distance: dist,
225	                time,
226	            });
227	        }
228	        matrix.push(matrix_row);
229	    }
230	    Ok(matrix)
231	}
