404	pub fn build_sweep_routes(
405	    matrix: &crate::core::vrp::types::DistMatrix,
406	    locations: &[crate::core::vrp::types::VRPSolverStop],
407	    num_vehicles: usize,
408	) -> Vec<Vec<usize>> {
409	    let n = locations.len();
410	    if n <= 1 {
411	        return vec![];
412	    }
413	    let depot = &locations[0];
414	    let mut indices: Vec<usize> = (1..n).collect();
415	    indices.sort_by(|&a, &b| {
416	        let la = &locations[a];
417	        let lb = &locations[b];
418	        let angle_a = (la.lat - depot.lat).atan2(la.lon - depot.lon);
419	        let angle_b = (lb.lat - depot.lat).atan2(lb.lon - depot.lon);
420	        angle_a.partial_cmp(&angle_b).unwrap_or(std::cmp::Ordering::Equal)
421	    });
422	
423	    let per_route = (indices.len() as f64 / num_vehicles as f64).ceil() as usize;
424	    let mut route_indices: Vec<Vec<usize>> = Vec::new();
425	
426	    for v in 0..num_vehicles {
427	        let start = v * per_route;
428	        let end = std::cmp::min(start + per_route, indices.len());
429	        if start >= indices.len() { break; }
430	        let segment = &indices[start..end];
431	        if segment.is_empty() { continue; }
432	
433	        let mut route = vec![0];
434	        let mut remaining: std::collections::HashSet<usize> = segment.iter().copied().collect();
435	        let mut current = 0;
436	        while !remaining.is_empty() {
437	            let mut best = 0;
438	            let mut best_dist = f64::INFINITY;
439	            for &node in &remaining {
440	                let dist = crate::core::vrp::utils::matrix_get_dist(matrix, current, node);
441	                if dist < best_dist {
442	                    best_dist = dist;
443	                    best = node;
444	                }
445	            }
446	            remaining.remove(&best);
447	            route.push(best);
448	            current = best;
449	        }
450	        route.push(0);
451	        route_indices.push(route);
452	    }
453	    route_indices
454	}
