  1	//! Route quality predictor.
  2	//!
  3	//! Predicts expected gap to optimal and tour length *before* solving,
  4	//! allowing early stopping or solver spawning decisions.
  5	//!
  6	//! Architecture: 28 → 64 → 32 → 2  (gap %, tour length km)
  7	//!
  8	//! Research basis: RouteFinder encoder + gap prediction (2406.15007)
  9	
 10	use crate::core::ml::features::InstanceFeatures;
 11	use anyhow::{Context, Result};
 12	use candle_core::{Device, DType, Tensor};
 13	use candle_nn::{linear, Linear, Module, VarBuilder};
 14	use serde::{Deserialize, Serialize};
 15	use std::path::Path;
 16	
 17	const NUM_FEATURES: usize = 28;
 18	const HIDDEN1: usize = 64;
 19	const HIDDEN2: usize = 32;
 20	const NUM_OUTPUTS: usize = 2;
 21	
 22	/// Predicted route quality metrics.
 23	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 24	pub struct QualityPrediction {
 25	    /// Predicted gap to optimal tour length (%).
 26	    pub predicted_gap_pct: f64,
 27	    /// Predicted absolute tour length (km).
 28	    pub predicted_tour_length_km: f64,
 29	    /// Confidence score [0,1] (if calibrated).
 30	    pub confidence: f64,
 31	    /// Whether the learned model was used (true) or heuristic fallback (false).
 32	    pub model_used: bool,
 33	}
 34	
 35	/// Learned MLP quality predictor.
 36	pub struct QualityPredictor {
 37	    lin1: Linear,
 38	    lin2: Linear,
 39	    lin3: Linear,
 40	    device: Device,
 41	}
 42	
 43	impl QualityPredictor {
 44	    /// Load from a safetensors file.
 45	    pub fn from_file(path: &Path) -> Result<Self> {
 46	        let device = crate::core::ml::best_device()?;
 47	        let tensors = candle_core::safetensors::load(path, &device)
 48	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 49	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 50	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 51	        let lin2 = linear(HIDDEN1, HIDDEN2, vb.pp("lin2"))?;
 52	        let lin3 = linear(HIDDEN2, NUM_OUTPUTS, vb.pp("lin3"))?;
 53	        Ok(Self { lin1, lin2, lin3, device })
 54	    }
 55	
 56	    /// Predict gap (%) and tour length (km) from instance features.
 57	    pub fn predict(&self, features: &InstanceFeatures) -> Result<QualityPrediction> {
 58	        let x = features.to_vector();
 59	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 60	        let h1 = self.lin1.forward(&input)?.relu()?;
 61	        let h2 = self.lin2.forward(&h1)?.relu()?;
 62	        let out = self.lin3.forward(&h2)?;
 63	        let vals: Vec<f32> = out.squeeze(0)?.to_vec1()?;
 64	
 65	        // gap is output 0, scaled to [0, 50]%
 66	        let gap = (vals[0].clamp(0.0, 1.0) * 50.0) as f64;
 67	        // tour length is output 1, scaled to [0, 5000] km
 68	        let tour = (vals[1].clamp(0.0, 1.0) * 5000.0) as f64;
 69	
 70	        Ok(QualityPrediction {
 71	            predicted_gap_pct: gap,
 72	            predicted_tour_length_km: tour,
 73	            confidence: 0.8,
 74	            model_used: true,
 75	        })
 76	    }
 77	}
