 936	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 937	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 938	        return RoadClass::all_vehicle();
 939	    };
 940	    if arr.is_empty() {
 941	        return RoadClass::all_vehicle();
 942	    }
 943	    arr.iter()
 944	        .filter_map(|v| v.as_str())
 945	        .filter_map(|s| match s {
 946	            "residential" => Some(RoadClass::Residential),
 947	            "tertiary" => Some(RoadClass::Tertiary),
 948	            "secondary" => Some(RoadClass::Secondary),
 949	            "primary" => Some(RoadClass::Primary),
 950	            "trunk" => Some(RoadClass::Trunk),
 951	            "motorway" => Some(RoadClass::Motorway),
 952	            "unclassified" => Some(RoadClass::Unclassified),
 953	            "living_street" => Some(RoadClass::LivingStreet),
 954	            "service" => Some(RoadClass::Service),
 955	            "secondary_link" => Some(RoadClass::SecondaryLink),
 956	            "primary_link" => Some(RoadClass::PrimaryLink),
 957	            "trunk_link" => Some(RoadClass::TrunkLink),
 958	            "motorway_link" => Some(RoadClass::MotorwayLink),
