1147	        .get("output")
1148	        .and_then(|v| v.as_str())
1149	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
1150	        .to_string();
1151	
1152	    // Build CleanOptions from args, using defaults where not specified
1153	    let defaults = CleanOptions::default();
1154	    let options = CleanOptions {
1155	        make_valid: args.get("make_valid").and_then(|v| v.as_bool()).unwrap_or(defaults.make_valid),
1156	        drop_invalid: args.get("drop_invalid").and_then(|v| v.as_bool()).unwrap_or(defaults.drop_invalid),
