1164	        max_components: args.get("max_components").and_then(|v| v.as_u64()).map(|v| v as usize).unwrap_or(defaults.max_components),
1165	        required_attrs: args.get("required_attrs").and_then(|v| v.as_array()).map(|arr| {
1166	            arr.iter().filter_map(|v| v.as_str().map(String::from)).collect()
1167	        }),
