1215	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1216	    let stops_val = args
1217	        .get("stops")
1218	        .and_then(|v| v.as_array())
1219	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1220	
1221	    if stops_val.is_empty() {
1222	        anyhow::bail!("At least one stop (the depot) is required");
1223	    }
1224	
1225	    let stops: Vec<VRPSolverStop> = stops_val
1226	        .iter()
1227	        .enumerate()
1228	        .map(|(i, s)| {
1229	            let lat = s.get("lat").and_then(|v| v.as_f64())
1230	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1231	            let lon = s.get("lon").and_then(|v| v.as_f64())
1232	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lon'", i))?;
1233	            let label = s.get("label").and_then(|v| v.as_str())
1234	                .unwrap_or_else(|| "")
1235	                .to_string();
1236	            let demand = s.get("demand").and_then(|v| v.as_f64());
1237	            Ok(VRPSolverStop {
1238	                lat,
1239	                lon,
1240	                label: if label.is_empty() { format!("Stop {}", i) } else { label },
1241	                demand,
1242	                arrival_time: None,
1243	            })
1244	        })
1245	        .collect::<Result<Vec<_>>>()?;
1246	
1247	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1248	    let vehicle_capacity = args.get("vehicle_capacity").and_then(|v| v.as_f64()).unwrap_or(100.0);
1249	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("default").to_string();
1250	    let avg_speed_kmh = args.get("avg_speed_kmh").and_then(|v| v.as_f64()).unwrap_or(40.0);
1251	    let objective = match args.get("objective").and_then(|v| v.as_str()).unwrap_or("min_distance") {
1252	        "min_time" => VrpObjective::MinTime,
1253	        "balance_load" => VrpObjective::BalanceLoad,
1254	        "min_vehicles" => VrpObjective::MinVehicles,
1255	        _ => VrpObjective::MinDistance,
1256	    };
1257	
1258	    // Build haversine distance matrix
1259	    let matrix = build_haversine_matrix(&stops, avg_speed_kmh);
1260	
1261	    #[cfg(feature = "ml")]
1262	    let mut input = VRPSolverInput {
1263	        locations: stops,
1264	        num_vehicles,
