28	pub fn log_solve(entry: SolveLogEntry, log_path: Option<&Path>) -> Result<()> {
29	    let path = log_path
30	        .map(|p| p.to_path_buf())
31	        .unwrap_or_else(default_log_path);
32	
33	    if let Some(parent) = path.parent() {
34	        std::fs::create_dir_all(parent)?;
35	    }
