163	/// Embed a road network graph.
164	///
165	/// Converts the nodes and edges to a line graph, uses a loaded GraphSAGE model
166	/// to produce 64-dim learned representations for each road segment.
167	pub fn embed_network(
168	    nodes: &[RmpNode],
169	    edges: &[RmpEdge],
170	    model_path: Option<&Path>,
171	) -> Vec<RoadEmbedding> {
172	    let path = model_path
173	        .map(|p| p.to_path_buf())
174	        .unwrap_or_else(default_model_path);
175	
176	    if !path.exists() {
177	        tracing::debug!("GraphSAGE model not found at {:?}, returning empty", path);
178	        return Vec::new();
179	    }
180	
181	    match try_embed_network(nodes, edges, &path) {
182	        Ok(embs) => embs,
183	        Err(e) => {
184	            tracing::warn!("GraphSAGE embedding failed: {}. Returning empty embeddings.", e);
185	            Vec::new()
186	        }
187	    }
188	}

  1	//! Natural Language Query Parser for VRP routing.
  2	//!
  3	//! Converts free-text routing requests into structured VRP JSON configs.
  4	//!
  5	//! Example:
  6	//!   "Route 50 packages with 5 vans starting at 45.5,-73.6 by 5pm"
  7	//!   → {"num_stops":50, "num_vehicles":5, "depot":[45.5,-73.6], "deadline":"17:00"}
  8	//!
  9	//! Research basis: "From Words to Routes" (2403.10795, 2024)
 10	//!
 11	//! Design: Hybrid approach
 12	//!   1. Regex-based entity extraction (numbers, coordinates, times)
 13	//!   2. Intent classification via keyword matching
 14	//!   3. Template-based JSON generation with slot filling
 15	//!   4. (Future) Small fine-tuned LLM for complex/ambiguous queries
