 8	/// Filter nodes and edges to only those within a bounding box.
 9	/// Returns remapped (nodes, edges) where edge indices are renumbered from 0.
10	/// If `bbox` is `None`, returns the originals unchanged.
11	#[allow(dead_code)]
12	pub fn filter_bbox(
13	    nodes: &[RmpNode],
14	    edges: &[RmpEdge],
15	    bbox: Option<BBox>,
16	) -> (Vec<RmpNode>, Vec<RmpEdge>) {
17	    let Some(bbox) = bbox else {
18	        return (nodes.to_vec(), edges.to_vec());
19	    };
20	
21	    // Mark which old-node indices are inside the bbox
22	    let inside: Vec<bool> = nodes
23	        .iter()
24	        .map(|n| bbox.contains(n.lon, n.lat))
25	        .collect();
26	
27	    // Build old->new index map
28	    let mut old_to_new = vec![u32::MAX; nodes.len()];
29	    let mut new_nodes = Vec::new();
30	    let mut next: u32 = 0;
31	    for (i, &is_inside) in inside.iter().enumerate() {
32	        if is_inside {
33	            old_to_new[i] = next;
34	            new_nodes.push(nodes[i]);
35	            next += 1;
36	        }
37	    }
38	
39	    // Keep edges whose both endpoints are inside
40	    let new_edges: Vec<RmpEdge> = edges
41	        .iter()
42	        .filter(|e| {
43	            let from_inside = inside.get(e.from as usize).copied().unwrap_or(false);
44	            let to_inside = inside.get(e.to as usize).copied().unwrap_or(false);
45	            from_inside && to_inside
46	        })
47	        .map(|e| RmpEdge {
48	            from: old_to_new[e.from as usize],
49	            to: old_to_new[e.to as usize],
50	            weight_m: e.weight_m,
51	            oneway: e.oneway,
52	        })
53	        .collect();
54	
55	    (new_nodes, new_edges)
56	}
