  3	use super::super::types::*;
  4	use super::super::utils::{matrix_get_dist, matrix_get_time};
  5	
  6	fn solve(
  7	    matrix: &DistMatrix,
  8	    locations: &[VRPSolverStop],
  9	    num_vehicles: usize,
 10	    hyperparams: Option<&SolverHyperparams>,
 11	) -> SolveResult {
 12	    let n = matrix.len();
 13	    if n <= 1 {
 14	        return SolveResult {
 15	            routes: vec![vec![0]],
 16	            total_distance: 0.0,
 17	            total_time: 0.0,
 18	        };
 19	    }
 20	
 21	    let mut routes = crate::core::vrp::utils::build_sweep_routes(matrix, locations, num_vehicles);
 22	    let max_iter = hyperparams.map(|p| p.max_iterations).unwrap_or(300);
 23	
 24	    // 2-opt improvement per route
 25	    for route in &mut routes {
 26	        let mut improved = true;
 27	        let mut iter = 0;
 28	        while improved && iter < max_iter {
 29	            improved = false;
 30	            iter += 1;
 31	            let r_len = route.len();
 32	            for i in 1..r_len.saturating_sub(1) {
 33	                for k in (i + 1)..r_len {
 34	                    let delta = matrix_get_dist(matrix, route[i - 1], route[k])
 35	                        + matrix_get_dist(matrix, route[i], route[k.min(route.len() - 1)])
 36	                        - matrix_get_dist(matrix, route[i - 1], route[i])
 37	                        - matrix_get_dist(matrix, route[k], route[k.min(route.len() - 1)]);
 38	                    if delta < -1e-9 {
 39	                        route[i..=k].reverse();
 40	                        improved = true;
 41	                    }
 42	                }
 43	            }
 44	        }
 45	    }
 46	
 47	    let final_routes: Vec<Vec<usize>> = routes.into_iter().filter(|r| r.len() > 2).collect();
 48	    if final_routes.is_empty() {
 49	        return SolveResult {
 50	            routes: vec![vec![0, 0]],
 51	            total_distance: 0.0,
 52	            total_time: 0.0,
 53	        };
 54	    }
 55	
 56	    let mut total_distance = 0.0;
 57	    let mut total_time = 0.0;
 58	    for r in &final_routes {
 59	        for i in 0..r.len() - 1 {
 60	            total_distance += matrix_get_dist(matrix, r[i], r[i + 1]);
 61	            total_time += matrix_get_time(matrix, r[i], r[i + 1]);
 62	        }
 63	    }
 64	
 65	    SolveResult {
 66	        routes: final_routes,
 67	        total_distance,
 68	        total_time,
 69	    }
 70	}
