 21	//! Geometric and routing utilities for VRP solvers.
 22	//!
 23	//! Provides distance-matrix construction, zone clustering,
 24	//! nearest-neighbor routing, 2-opt improvement, and Valhalla matrix fetching.
 25	
 26	use super::super::haversine_m;
 27	use super::types::{DistCell, DistMatrix, VRPSolverStop};
 28	
 29	/// Haversine distance between two WGS-84 coordinates, in km.
 30	pub fn haversine_km(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
 31	    haversine_m(lat1, lon1, lat2, lon2) / 1000.0
 32	}
 33	
 34	/// Build a full O(n²) distance/time matrix using haversine.
 35	/// Time estimated at `avg_speed_kmh` (default 40 km/h).
 36	pub fn build_haversine_matrix(locations: &[VRPSolverStop], avg_speed_kmh: f64) -> DistMatrix {
 37	    let n = locations.len();
 38	    let mut matrix = Vec::with_capacity(n);
 39	    for (i, _) in locations.iter().enumerate().take(n) {
 40	        let mut row = Vec::with_capacity(n);
 41	        for j in 0..n {
 42	            let dist = haversine_km(
 43	                locations[i].lat,
 44	                locations[i].lon,
 45	                locations[j].lat,
 46	                locations[j].lon,
 47	            );
 48	            let time_sec = (dist / avg_speed_kmh) * 3600.0;
 49	            row.push(DistCell {
 50	                distance: dist,
 51	                time: time_sec,
 52	            });
 53	        }
 54	        matrix.push(row);
 55	    }
 56	    matrix
 57	}
 58	
 59	/// Build a distance matrix using shortest paths on the road network graph.
 60	pub fn build_graph_matrix(
 61	    stops: &[VRPSolverStop],
 62	    nodes: &[RmpNode],
 63	    edges: &[RmpEdge],
 64	    embeddings: Option<&[crate::core::ml::graph_embed::RoadEmbedding]>,
 65	    avg_speed_kmh: f64,
 66	) -> DistMatrix {
 67	    let n_stops = stops.len();
 68	    let n_nodes = nodes.len();
 69	    if n_stops == 0 || n_nodes == 0 {
 70	        return vec![vec![DistCell { distance: 0.0, time: 0.0 }; n_stops]; n_stops];
 71	    }
 72	
 73	    // 1. Build adjacency list
 74	    let mut adj = vec![Vec::new(); n_nodes];
 75	    for (i, edge) in edges.iter().enumerate() {
 76	        let mut weight = edge.weight_m;
 77	        
 78	        // Apply learned embedding if available
 79	        if let Some(embs) = embeddings {
 80	            if let Some(emb) = embs.get(i) {
 81	                // Use first dimension as a learned bias for now
 82	                // Research basis: GAIN (2107.07791)
 83	                let bias = emb.vector.get(0).copied().unwrap_or(0.0);
 84	                weight *= (1.0 + bias as f64).max(0.1);
 85	            }
 86	        }
 87	
 88	        adj[edge.from as usize].push((edge.to as usize, weight));
 89	        if edge.oneway == 0 {
 90	            adj[edge.to as usize].push((edge.from as usize, weight));
 91	        }
 92	    }
 93	
 94	    // 2. Map stops to nearest nodes
 95	    let stop_nodes: Vec<usize> = stops.iter().map(|stop| {
 96	        let mut best_node = 0;
 97	        let mut best_dist = f64::MAX;
 98	        for (i, node) in nodes.iter().enumerate() {
 99	            let d = haversine_m(stop.lat, stop.lon, node.lat, node.lon);
100	            if d < best_dist {
101	                best_dist = d;
102	                best_node = i;
103	            }
104	        }
105	        best_node
106	    }).collect();
107	
108	    // 3. Dijkstra from each stop node
109	    let mut matrix = vec![vec![DistCell { distance: 0.0, time: 0.0 }; n_stops]; n_stops];
110	    
111	    for i in 0..n_stops {
112	        let start_node = stop_nodes[i];
113	        let dists = dijkstra(start_node, &adj, n_nodes);
114	        
115	        for j in 0..n_stops {
116	            let target_node = stop_nodes[j];
117	            let d_m = dists[target_node];
118	            let d_km = d_m / 1000.0;
119	            let time_sec = (d_km / avg_speed_kmh) * 3600.0;
120	            matrix[i][j] = DistCell { distance: d_km, time: time_sec };
121	        }
122	    }
123	
124	    matrix
125	}
126	
127	fn dijkstra(start: usize, adj: &[Vec<(usize, f64)>], n: usize) -> Vec<f64> {
128	    use std::collections::BinaryHeap;
129	    use std::cmp::Ordering;
130	
131	    #[derive(Copy, Clone, PartialEq)]
132	    struct State {
133	        cost: f64,
134	        position: usize,
135	    }
136	    impl Eq for State {}
137	    impl Ord for State {
138	        fn cmp(&self, other: &Self) -> Ordering {
139	            other.cost.partial_cmp(&self.cost).unwrap_or(Ordering::Equal)
140	        }
141	    }
142	    impl PartialOrd for State {
143	        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
144	            Some(self.cmp(other))
145	        }
146	    }
147	
148	    let mut dists = vec![f64::MAX; n];
149	    let mut heap = BinaryHeap::new();
150	
151	    dists[start] = 0.0;
152	    heap.push(State { cost: 0.0, position: start });
153	
154	    while let Some(State { cost, position }) = heap.pop() {
155	        if cost > dists[position] { continue; }
156	
157	        for (next, weight) in &adj[position] {
158	            let next_cost = cost + weight;
159	            if next_cost < dists[*next] {
160	                dists[*next] = next_cost;
161	                heap.push(State { cost: next_cost, position: *next });
162	            }
163	        }
164	    }
165	    dists
166	}
