233	/// Cluster stops into geographic grid zones so nearby stops are grouped together.
234	pub fn cluster_by_zones(locations: &[VRPSolverStop], num_zones: usize) -> Vec<Vec<usize>> {
235	    let n = locations.len();
236	    if n <= num_zones {
237	        return (0..n).map(|i| vec![i]).collect();
238	    }
239	    let min_lat = locations
240	        .iter()
241	        .map(|p| p.lat)
242	        .fold(f64::INFINITY, f64::min);
243	    let max_lat = locations
244	        .iter()
245	        .map(|p| p.lat)
246	        .fold(f64::NEG_INFINITY, f64::max);
247	    let min_lon = locations
248	        .iter()
249	        .map(|p| p.lon)
250	        .fold(f64::INFINITY, f64::min);
251	    let max_lon = locations
252	        .iter()
253	        .map(|p| p.lon)
254	        .fold(f64::NEG_INFINITY, f64::max);
255	
256	    let rows = (num_zones as f64).sqrt().ceil() as usize;
257	    let cols = num_zones.div_ceil(rows); // ceil division
258	    let cell_lat = (max_lat - min_lat) / rows as f64;
259	    let cell_lon = (max_lon - min_lon) / cols as f64;
260	    let cell_lat = if cell_lat == 0.0 { 0.001 } else { cell_lat };
261	    let cell_lon = if cell_lon == 0.0 { 0.001 } else { cell_lon };
262	
263	    let mut grid: std::collections::BTreeMap<(usize, usize), Vec<usize>> =
264	        std::collections::BTreeMap::new();
265	    for (i, _) in locations.iter().enumerate().take(n) {
266	        let p = &locations[i];
267	        let ri = ((p.lat - min_lat) / cell_lat).floor() as usize;
268	        let ri = ri.min(rows - 1);
269	        let ci = ((p.lon - min_lon) / cell_lon).floor() as usize;
270	        let ci = ci.min(cols - 1);
271	        grid.entry((ri, ci)).or_default().push(i);
272	    }
273	    grid.into_values().collect()
274	}
