276	/// Order clusters so the start zone comes first, then nearest by centroid.
277	pub fn order_clusters_by_start(
278	    clusters: &[Vec<usize>],
279	    locations: &[VRPSolverStop],
280	    start_index: usize,
281	) -> Vec<Vec<usize>> {
282	    let start = &locations[start_index];
283	    let mut with_centroid: Vec<(Vec<usize>, f64, bool)> = clusters
284	        .iter()
285	        .map(|indices| {
286	            let lat: f64 =
287	                indices.iter().map(|&i| locations[i].lat).sum::<f64>() / indices.len() as f64;
288	            let lon: f64 =
289	                indices.iter().map(|&i| locations[i].lon).sum::<f64>() / indices.len() as f64;
290	            let dist = haversine_km(start.lat, start.lon, lat, lon);
291	            let contains_start = indices.contains(&start_index);
292	            (indices.clone(), dist, contains_start)
293	        })
294	        .collect();
295	
296	    with_centroid.sort_by(|a, b| {
297	        if a.2 && !b.2 {
298	            std::cmp::Ordering::Less
299	        } else if !a.2 && b.2 {
300	            std::cmp::Ordering::Greater
301	        } else {
302	            a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal)
303	        }
304	    });
305	
306	    with_centroid
307	        .into_iter()
308	        .map(|(indices, _, _)| indices)
309	        .collect()
310	}
