312	/// Nearest-neighbor TSP construction for a subset of indices.
313	pub fn nearest_neighbor_route(
314	    matrix: &DistMatrix,
315	    indices: &[usize],
316	    start_idx_in_subset: usize,
317	) -> Vec<usize> {
318	    if indices.len() <= 1 {
319	        return indices.to_vec();
320	    }
321	    let mut route = Vec::with_capacity(indices.len());
322	    let mut remaining: std::collections::HashSet<usize> = indices.iter().copied().collect();
323	    let start_global = indices[start_idx_in_subset];
324	    route.push(start_global);
325	    remaining.remove(&start_global);
326	    let mut current = start_global;
327	    while !remaining.is_empty() {
328	        let mut nearest = 0;
329	        let mut best_dist = f64::INFINITY;
330	        for &i in &remaining {
331	            let d = matrix
332	                .get(current)
333	                .and_then(|row| row.get(i))
334	                .map(|c| c.distance)
335	                .unwrap_or(f64::INFINITY);
336	            if d < best_dist {
337	                best_dist = d;
338	                nearest = i;
339	            }
340	        }
341	        route.push(nearest);
342	        remaining.remove(&nearest);
343	        current = nearest;
344	    }
345	    route
346	}
