348	/// 2-opt improvement: iteratively reverse segments to reduce total distance.
349	pub fn two_opt_improve(
350	    matrix: &DistMatrix,
351	    route_indices: &[usize],
352	    max_iter: u32,
353	) -> Vec<usize> {
354	    let n = route_indices.len();
355	    if n <= 3 {
356	        return route_indices.to_vec();
357	    }
358	    let mut route = route_indices.to_vec();
359	    let mut improved = true;
360	    let mut iterations = 0;
361	    while improved && iterations < max_iter {
362	        improved = false;
363	        iterations += 1;
364	        for i in 0..n - 2 {
365	            for j in (i + 2)..n {
366	                let a = route[i];
367	                let b = route[i + 1];
368	                let c = route[j];
369	                let d = route[(j + 1) % n];
370	                let before = matrix_get_dist(matrix, a, b) + matrix_get_dist(matrix, c, d);
371	                let after = matrix_get_dist(matrix, a, c) + matrix_get_dist(matrix, b, d);
372	                if after < before - 1e-6 {
373	                    route[i + 1..=j].reverse();
374	                    improved = true;
375	                    break;
376	                }
377	            }
378	            if improved {
379	                break;
380	            }
381	        }
382	    }
383	    route
384	}
