386	/// Helper: get distance from matrix with fallback.
387	pub fn matrix_get_dist(matrix: &DistMatrix, i: usize, j: usize) -> f64 {
388	    matrix
389	        .get(i)
390	        .and_then(|row| row.get(j))
391	        .map(|c| c.distance)
392	        .unwrap_or(0.0)
393	}
