396	pub fn matrix_get_time(matrix: &DistMatrix, i: usize, j: usize) -> f64 {
397	    matrix
398	        .get(i)
399	        .and_then(|row| row.get(j))
400	        .map(|c| c.time)
401	        .unwrap_or(0.0)
402	}
