458	/// Parse a CSV file of coordinates into VRP solver stops.
459	///
460	/// Supported column sets:
461	///   Minimal:  lat,lon
462	///   Extended: lat,lon,label,demand,type
463	///
464	/// The `type` column accepts "depot" or "stop" (default: "stop").
465	/// If no depot is present, the first row becomes the depot.
466	/// The `demand` column is optional; defaults to 1.0 for stops, 0.0 for depots.
467	pub fn parse_csv_stops(csv_path: &str) -> Result<(Vec<crate::core::vrp::types::VRPSolverStop>, Vec<usize>), String> {
468	    use std::io::Read;
469	    let mut file = std::fs::File::open(csv_path)
470	        .map_err(|e| format!("Cannot open CSV '{}': {}", csv_path, e))?;
471	    let mut content = String::new();
472	    file.read_to_string(&mut content)
473	        .map_err(|e| format!("Cannot read CSV '{}': {}", csv_path, e))?;
474	
475	    let mut reader = csv::ReaderBuilder::new()
476	        .has_headers(true)
477	        .trim(csv::Trim::All)
478	        .from_reader(content.as_bytes());
479	
480	    let headers = reader.headers()
481	        .map_err(|e| format!("Failed to read CSV headers: {}", e))?
482	        .clone();
483	
484	    let lat_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("lat") || h.eq_ignore_ascii_case("latitude"))
485	        .ok_or("CSV must have a 'lat' column")?;
486	    let lon_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("lon") || h.eq_ignore_ascii_case("lng") || h.eq_ignore_ascii_case("longitude"))
487	        .ok_or("CSV must have a 'lon' column")?;
488	    let label_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("label") || h.eq_ignore_ascii_case("name") || h.eq_ignore_ascii_case("id"));
489	    let demand_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("demand"));
490	    let type_idx = headers.iter().position(|h| h.eq_ignore_ascii_case("type") || h.eq_ignore_ascii_case("role"));
491	
492	    let mut stops = Vec::new();
493	    let mut depot_indices = Vec::new();
494	
495	    for (row_num, result) in reader.records().enumerate() {
496	        let record = result.map_err(|e| format!("CSV parse error at row {}: {}", row_num + 2, e))?;
497	
498	        let lat: f64 = record.get(lat_idx)
499	            .ok_or_else(|| format!("Missing lat at row {}", row_num + 2))?
500	            .parse()
501	            .map_err(|e| format!("Invalid lat at row {}: {}", row_num + 2, e))?;
502	        let lon: f64 = record.get(lon_idx)
503	            .ok_or_else(|| format!("Missing lon at row {}", row_num + 2))?
504	            .parse()
505	            .map_err(|e| format!("Invalid lon at row {}: {}", row_num + 2, e))?;
506	
507	        let label = label_idx
508	            .and_then(|i| record.get(i))
509	            .map(|s| s.to_string())
510	            .unwrap_or_else(|| format!("stop_{}", row_num));
511	
512	        let is_depot = type_idx
513	            .and_then(|i| record.get(i))
514	            .map(|s| s.eq_ignore_ascii_case("depot"))
515	            .unwrap_or(false);
516	
517	        let demand = demand_idx
518	            .and_then(|i| record.get(i))
519	            .and_then(|s| s.parse::<f64>().ok())
520	            .unwrap_or(if is_depot { 0.0 } else { 1.0 });
521	
522	        if is_depot {
523	            depot_indices.push(stops.len());
524	        }
525	
526	        stops.push(crate::core::vrp::types::VRPSolverStop {
527	            lat,
528	            lon,
529	            label,
530	            demand: Some(demand),
531	            arrival_time: None,
532	        });
533	    }
534	
535	    if stops.is_empty() {
536	        return Err("CSV file contains no data rows".to_string());
537	    }
538	
539	    // If no depot was found, designate the first stop as depot
540	    if depot_indices.is_empty() {
541	        depot_indices.push(0);
542	        if let Some(d) = stops[0].demand.as_mut() {
543	            *d = 0.0;
544	        }
545	    }
546	
547	    Ok((stops, depot_indices))
548	}
