arguments.new_str:
const NUM_FEATURES: usize = 28;
const HIDDEN1: usize = 128;
const HIDDEN2: usize = 64;
const NUM_SOLVERS: usize = 6;

const SOLVER_IDS: [&str; NUM_SOLVERS] = [
    "default",
    "clarke_wright",
    "sweep",
    "or_opt",
    "two_opt",
    "neural_guided",
];

/// Predict best solver using cost-sensitive argmin-regret.
pub fn predict(&self,
    features: &InstanceFeatures,
) -> Result<NeuralPrediction> {
    let x = features.to_vector();
    let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
    let h1 = self.lin1.forward(&input)?.relu()?;
    let h2 = self.lin2.forward(&h1)?.relu()?;
    let out = self.lin3.forward(&h2)?;
    // Model predicts regret per solver → lower is better.
    let vals: Vec<f32> = out.squeeze(0)?.to_vec1()?;
    let mut indexed: Vec<(usize, f32)> = vals.iter().enumerate().map(|(i, &v)| (i, v)).collect();
    indexed.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));

    let best_idx = indexed[0].0;
    let best_regret = indexed[0].1;
    let runner_up = indexed.get(1).map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v));

    // Report raw regrets as scores (lower = better)
    let all_scores: Vec<(String, f64)> = indexed
        .iter()
        .map(|(i, v)| (SOLVER_IDS[*i].to_string(), *v as f64))
        .collect();

    // Convert regret to a pseudo-confidence: high regret spread → less confident
    let max_regret = indexed.last().map(|(_, v)| *v).unwrap_or(1.0);
    let confidence = if max_regret > 1e-6 {
        (1.0 - (best_regret / max_regret)).clamp(0.0, 1.0) as f64
    } else {
        1.0
    };

    Ok(NeuralPrediction {
        recommended: SOLVER_IDS[best_idx].to_string(),
        confidence,
        runner_up,
        all_scores,
    })
}

